def cell(block,resource):return block.replace("Materna-","Materna ")+" / "+resource
def pct(v):return f"{float(v):+.6f}"
def value(v):return f"{float(v):.7g}"

def readable_prose(text):
    # Typography only; protect source links, paths, hashes and literal formulae.
    pieces=re.split(r"(`[^`]*`|\[[^\]]*\]\([^)]*\))",text)
    for index in range(0,len(pieces),2):
        part=pieces[index].replace("Date:23 October2026","Date: 23 October 2026").replace("Stage18","Stage 18")
        for _ in range(3):
            part=re.sub(r"\b(all|All|the|The|in|In|of|Of|is|are|has|exactly|on|to|versus|and|or|not|near|attributes|from|at|alpha|alphas|lead|leads|count|origin|Across|across|improves|worsens|ties|top|uses|its|range|ARX|ratio|excess|contributes|contribute|correct|MAE)(?=\d)",r"\1 ",part)
            part=re.sub(r"(?<![A-Za-z])(\d+(?:\.\d+)?)(?=(?:final|inner|exact|new|historical|contexts|external|recovery|saved|sign|stable|variable|candidate|machine|groups|checks|files|protected|positive|negative|zero|ties|undefined|S2|M1|rows|scientific|completed|contribute|cells|values|post|in|to|and|versus|on))",r"\1 ",part)
        part=re.sub(r"('s|:)(?=\d)",r"\1 ",part).replace("are+infinity","are +infinity").replace("L128","L=128")
        part=part.replace("%to","% to ").replace("%onT","% on T").replace("reuses+","reuses + ").replace("inner+","inner + ").replace(";35","; 35").replace("+5712","+ 5712").replace("+2730","+ 2730").replace("+7280","+ 7280")
        part=re.sub(r",(?=[A-Za-z0-9])",", ",part)
        pieces[index]=part
    return "".join(pieces).replace("Branch:`","Branch: `").replace("HEAD:`","HEAD: `").replace("[Main48-row","[Main 48-row")

